from __future__ import annotations

from fastapi import FastAPI
from fastapi.responses import HTMLResponse


DASHBOARD_HTML = r"""
<!doctype html>
<html lang="zh-Hant">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>BTC 5m Adaptive Guarded</title>
<style>
:root{color-scheme:dark;--bg:#07111f;--panel:#10213a;--line:#2a405e;--text:#eef5ff;--muted:#9fb2cc;--yes:#2ed573;--no:#ff6b6b;--wait:#f6c344}
*{box-sizing:border-box}body{margin:0;background:#07111f;color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1080px;margin:auto;padding:16px 14px 34px}.top{display:flex;justify-content:space-between;gap:12px}.title{font-size:24px;font-weight:900}.sub,.muted{color:var(--muted);font-size:13px}.pill{border:1px solid var(--line);padding:8px 12px;border-radius:999px;font-weight:800;font-size:12px;background:#0c1b31}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px;margin-top:14px}.card{grid-column:span 12;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:14px}.mini{grid-column:span 6}.third{grid-column:span 4}.quarter{grid-column:span 3}.label{color:var(--muted);font-size:13px}.value{font-size:29px;font-weight:900;margin-top:4px}.small{font-size:19px;font-weight:850;margin-top:4px}.row{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid rgba(159,178,204,.16)}.row:last-child{border-bottom:0}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;overflow-wrap:anywhere}.yes{color:var(--yes)}.no{color:var(--no)}.wait{color:var(--wait)}a{color:#b9e6ff;text-decoration:none;margin-right:10px;display:inline-block;margin-top:8px}@media(max-width:720px){.mini,.third,.quarter{grid-column:span 12}.title{font-size:21px}}
</style>
</head>
<body>
<main class="wrap">
<header class="top"><div><div class="title">BTC 5 分鐘預測市場</div><div class="sub">V3 Adaptive Guarded · 50% → 30% → 20% · Paper Only</div></div><div id="system" class="pill">LOADING</div></header>
<section class="grid">
<article class="card mini"><div class="label">本輪 AI 判斷</div><div id="direction" class="value wait">WAIT</div><div id="reason" class="muted">等待資料同步</div></article>
<article class="card mini"><div class="label">距離本輪結束</div><div id="countdown" class="value">--:--</div><div class="muted">五分鐘結束後自動結算</div></article>
<article class="card quarter"><div class="label">BTC 上漲機率</div><div id="probability" class="small">—</div></article>
<article class="card quarter"><div class="label">AI 信心</div><div id="confidence" class="small">—</div></article>
<article class="card quarter"><div class="label">Paper 勝率</div><div id="winRate" class="small">0.00%</div></article>
<article class="card quarter"><div class="label">已實現 PnL</div><div id="pnl" class="small">$0.0000</div></article>
<article class="card mini"><h3>Adaptive Cooldown</h3><div class="row"><span>冷卻狀態</span><strong id="cooldown">OFF</strong></div><div class="row"><span>連敗輪次</span><strong id="lossStreak">0</strong></div><div class="row"><span>觸發門檻</span><strong id="cooldownThreshold">3</strong></div><div class="row"><span>剩餘時間</span><strong id="cooldownRemaining">0 秒</strong></div><div class="row"><span>自動調參</span><strong>OFF</strong></div></article>
<article class="card mini"><h3>BTC Regime</h3><div class="row"><span>狀態</span><strong id="regime">—</strong></div><div class="row"><span>Net Move</span><strong id="netMove">—</strong></div><div class="row"><span>Range</span><strong id="range">—</strong></div><div class="row"><span>Flip Ratio</span><strong id="flipRatio">—</strong></div><div class="row"><span>Direction Consistency</span><strong id="consistency">—</strong></div></article>
<article class="card mini"><h3>模型校準</h3><div class="row"><span>Rolling Win Rate</span><strong id="rollingWinRate">—</strong></div><div class="row"><span>Rolling PnL</span><strong id="rollingPnl">—</strong></div><div class="row"><span>Brier Score</span><strong id="brierScore">—</strong></div><div class="row"><span>平均預測機率</span><strong id="avgExpected">—</strong></div><div class="row"><span>實際命中率</span><strong id="observedRate">—</strong></div><div class="row"><span>過度自信警示</span><strong id="overconfidenceCount">0</strong></div><div class="row"><span>Review 建議</span><strong id="reviewCount">0</strong></div></article>
<article class="card mini"><h3>Performance Drift</h3><div class="row"><span>Drift 狀態</span><strong id="driftStatus">—</strong></div><div class="row"><span>近期勝率下降</span><strong id="driftWinRateDrop">—</strong></div><div class="row"><span>Rolling Brier</span><strong id="rollingBrier">—</strong></div><div class="row"><span>Brier 惡化幅度</span><strong id="brierIncrease">—</strong></div><div class="row"><span>近期樣本數</span><strong id="driftSamples">0</strong></div><div class="row"><span>Drift 原因</span><strong id="driftReasons" class="mono">—</strong></div></article>
<article class="card mini"><h3>目前市場</h3><div class="row"><span>市場狀態</span><strong id="marketStatus">—</strong></div><div class="row"><span>Slug</span><strong id="slug" class="mono">—</strong></div><div class="row"><span>YES Ask</span><strong id="yesAsk">—</strong></div><div class="row"><span>NO Ask</span><strong id="noAsk">—</strong></div><div class="row"><span>YES Book Age</span><strong id="yesBookAge">—</strong></div><div class="row"><span>NO Book Age</span><strong id="noBookAge">—</strong></div></article>
<article class="card mini"><h3>本輪倉位</h3><div class="row"><span>BTC 開盤價</span><strong id="btcOpen">—</strong></div><div class="row"><span>BTC 收盤價</span><strong id="btcClose">—</strong></div><div class="row"><span>合約進場價</span><strong id="entryPrice">—</strong></div><div class="row"><span>模擬本金</span><strong id="notional">—</strong></div><div class="row"><span>已完成加倉</span><strong id="scaleCount">0 / 3</strong></div><div class="row"><span>結算結果</span><strong id="outcome">—</strong></div></article>
<article class="card mini"><h3>最新品質檢查</h3><div class="row"><span>Signal Source</span><strong id="signalSource">—</strong></div><div class="row"><span>Signal Age</span><strong id="signalAge">—</strong></div><div class="row"><span>Book Age</span><strong id="bookAge">—</strong></div><div class="row"><span>Spread</span><strong id="spread">—</strong></div><div class="row"><span>Net Edge</span><strong id="netEdge">—</strong></div><div class="row"><span>Depth / Required</span><strong id="depth">—</strong></div></article>
<article class="card mini"><h3>安全模式</h3><div class="row"><span>執行模式</span><strong id="execution">—</strong></div><div class="row"><span>Paper 預測</span><strong id="paper">ON</strong></div><div class="row"><span>真實下單</span><strong id="live">OFF</strong></div><div class="row"><span>錢包簽名</span><strong id="wallet">OFF</strong></div><div class="row"><span>拒絕次數</span><strong id="rejected">0</strong></div></article>
<article class="card"><h3>拒絕原因統計</h3><pre id="rejections" class="mono">{}</pre></article>
<article class="card"><a href="/mode">/mode</a><a href="/status">/status</a><a href="/paper/winrate">/paper/winrate</a><a href="/paper/analytics">/paper/analytics</a><a href="/paper/rounds">/paper/rounds</a><a href="/healthz">/healthz</a><a href="/docs">/docs</a><div id="updated" class="muted"></div></article>
</section>
</main>
<script>
const $=id=>document.getElementById(id),pct=x=>Number.isFinite(Number(x))?`${(Number(x)*100).toFixed(2)}%`:'—',num=x=>Number.isFinite(Number(x))?Number(x).toFixed(4):'—',usd=x=>Number.isFinite(Number(x))?`$${Number(x).toFixed(4)}`:'—',ms=x=>Number.isFinite(Number(x))?`${Math.round(Number(x))} ms`:'—';
function cd(c){let start=Number(c?.interval_start||0);if(!start){const m=String(c?.slug||'').match(/(\d{10})$/);if(m)start=Number(m[1])}if(!start)return'--:--';const r=Math.max(0,start+300-Math.floor(Date.now()/1000));return`${String(Math.floor(r/60)).padStart(2,'0')}:${String(r%60).padStart(2,'0')}`}
function klass(d){return d==='YES'?'yes':d==='NO'?'no':'wait'}
async function refresh(){try{const [s,m]=await Promise.all([fetch('/status',{cache:'no-store'}).then(r=>r.json()),fetch('/mode',{cache:'no-store'}).then(r=>r.json())]);const paper=s.paper||{},sum=paper.summary||{},round=paper.current_round||{},guard=paper.adaptive_guard||{},analytics=paper.analytics||{},cool=analytics.cooldown||{},rolling=analytics.rolling||{},cal=analytics.calibration||{},drift=analytics.drift||{},review=analytics.review||{},fusion=s.fusion||{},reg=fusion.regime||{},market=s.market||{},current=market.current||{},ai=s.ai||{},q=ai.last_signal_quality||{},safe=m.safety||{};const d=round.direction||ai.direction||'WAIT';$('direction').textContent=d;$('direction').className=`value ${klass(d)}`;$('reason').textContent=round.reason||ai.reason||'等待資料同步';$('countdown').textContent=cd(current);$('probability').textContent=pct(ai.probability_up);$('confidence').textContent=pct(ai.confidence);$('winRate').textContent=pct(sum.win_rate||0);$('pnl').textContent=usd(sum.realized_pnl||0);$('cooldown').textContent=guard.cooldown_active?'ACTIVE':'OFF';$('cooldown').className=guard.cooldown_active?'no':'yes';$('lossStreak').textContent=cool.consecutive_round_losses||0;$('cooldownThreshold').textContent=guard.cooldown_after_losses||3;$('cooldownRemaining').textContent=`${Math.ceil(Number(guard.cooldown_remaining_ms||0)/1000)} 秒`;$('regime').textContent=reg.status||fusion.status||'—';$('netMove').textContent=num(reg.net_move_bps);$('range').textContent=num(reg.range_bps);$('flipRatio').textContent=pct(reg.flip_ratio);$('consistency').textContent=pct(reg.direction_consistency);$('rollingWinRate').textContent=pct(rolling.win_rate);$('rollingPnl').textContent=usd(rolling.pnl);$('brierScore').textContent=num(cal.brier_score);$('avgExpected').textContent=pct(cal.average_expected_probability);$('observedRate').textContent=pct(cal.observed_win_rate);$('overconfidenceCount').textContent=(cal.overconfidence_reviews||[]).length;$('reviewCount').textContent=review.recommendation_count||0;$('driftStatus').textContent=drift.review_only?'REVIEW':'OK';$('driftStatus').className=drift.review_only?'no':'yes';$('driftWinRateDrop').textContent=pct(drift.win_rate_drop);$('rollingBrier').textContent=num(drift.rolling_brier_score);$('brierIncrease').textContent=num(drift.brier_increase);$('driftSamples').textContent=drift.samples||0;$('driftReasons').textContent=(drift.reasons||[]).join(', ')||'—';$('marketStatus').textContent=market.discovery_status||'—';$('slug').textContent=current.slug||'—';$('yesAsk').textContent=num(market.yes_ask);$('noAsk').textContent=num(market.no_ask);$('yesBookAge').textContent=ms(market.yes_book_age_ms);$('noBookAge').textContent=ms(market.no_book_age_ms);$('btcOpen').textContent=num(round.btc_open);$('btcClose').textContent=num(round.btc_close);$('entryPrice').textContent=num(round.entry_price);$('notional').textContent=usd(round.notional_usd);$('scaleCount').textContent=`${Number(round.order_count||0)} / 3`;$('outcome').textContent=round.outcome||'—';$('signalSource').textContent=q.signal_source||'—';$('signalAge').textContent=ms(q.signal_age_ms);$('bookAge').textContent=ms(q.book_age_ms);$('spread').textContent=num(q.spread);$('netEdge').textContent=pct(q.net_edge);$('depth').textContent=`${usd(q.ask_depth_usd)} / ${usd(q.required_depth_usd)}`;$('execution').textContent=m.execution||'—';$('paper').textContent=safe.paper_predictions_enabled?'ON':'OFF';$('live').textContent=safe.live_orders_enabled?'ON':'OFF';$('wallet').textContent=safe.wallet_signing_enabled?'ON':'OFF';$('rejected').textContent=s.execution_metrics?.predictions_rejected||0;$('rejections').textContent=JSON.stringify(sum.rejection_counts||{},null,2);const active=market.discovery_status==='ready';$('system').textContent=guard.cooldown_active?'COOLDOWN':active?'SYSTEM ACTIVE':'WAITING';$('system').className=`pill ${guard.cooldown_active?'no':active?'yes':'wait'}`;$('updated').textContent=`更新時間 ${new Date().toLocaleTimeString()}`}catch(e){$('system').textContent='OFFLINE';$('system').className='pill no'}}
refresh();setInterval(refresh,1500);
</script>
</body></html>
"""


def register_btc5m_prediction_market_ui(app: FastAPI) -> None:
    @app.get("/ui", response_class=HTMLResponse)
    async def dedicated_ui() -> HTMLResponse:
        return HTMLResponse(DASHBOARD_HTML)
